def run_trace(items,k):
    reset_trace()
    emit("start",k)
    pipeline=map(transform,filter(accept,source(items)))
    answer=[]
    for _ in range(k):
        try:value=next(pipeline)
        except StopIteration:break
        answer.append(value)
        emit("output",value)
    return answer
